{
  "PROP-6a4369e9-inv-028": {
    "property_id": "PROP-6a4369e9-inv-028",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-028",
      "classification": "vulnerability",
      "code_path": "beacon-chain/sync/rpc_blob_sidecars_by_range.go::BlobRPCMinValidSlot::L136-148",
      "proof_trace": "Missing Fulu deprecation check. After FULU_FORK_EPOCH + MIN_EPOCHS, BlobRPCMinValidSlot still calculates minStart = currEpoch - minReqEpochs, allowing recent blobs to be served indefinitely. Should reject all requests or return far-future slot once deprecation deadline passes.",
      "attack_scenario": "After current epoch >= FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS, peer sends BlobSidecarsByRangeRequest for recent slots. Handler serves blobs instead of responding empty, violating protocol deprecation requirement and preventing migration to data columns.",
      "checklist_id": "PROP-6a4369e9-inv-028"
    },
    "text": "blob_sidecars_by_range must be fully deprecated after FULU_FORK_EPOCH + MIN_EPOCHS.",
    "assertion": "current_epoch >= FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS => respond_empty_or_reject",
    "covers": "SG-011",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

