     1→package sync
     2→
     3→import (
     4→	"context"
     5→	"math"
     6→	"time"
     7→
     8→	"github.com/OffchainLabs/prysm/v6/beacon-chain/p2p"
     9→	p2ptypes "github.com/OffchainLabs/prysm/v6/beacon-chain/p2p/types"
    10→	"github.com/OffchainLabs/prysm/v6/cmd/beacon-chain/flags"
    11→	"github.com/OffchainLabs/prysm/v6/config/params"
    12→	"github.com/OffchainLabs/prysm/v6/consensus-types/primitives"
    13→	"github.com/OffchainLabs/prysm/v6/monitoring/tracing"
    14→	"github.com/OffchainLabs/prysm/v6/monitoring/tracing/trace"
    15→	pb "github.com/OffchainLabs/prysm/v6/proto/prysm/v1alpha1"
    16→	"github.com/OffchainLabs/prysm/v6/time/slots"
    17→	libp2pcore "github.com/libp2p/go-libp2p/core"
    18→	"github.com/pkg/errors"
    19→)
    20→
    21→func (s *Service) streamBlobBatch(ctx context.Context, batch blockBatch, wQuota uint64, stream libp2pcore.Stream) (uint64, error) {
    22→	// Defensive check to guard against underflow.
    23→	if wQuota == 0 {
    24→		return 0, nil
    25→	}
    26→	_, span := trace.StartSpan(ctx, "sync.streamBlobBatch")
    27→	defer span.End()
    28→	for _, b := range batch.canonical() {
    29→		root := b.Root()
    30→		idxs := s.cfg.blobStorage.Summary(root)
    31→		for i := range idxs.MaxBlobsForEpoch() {
    32→			// index not available, skip
    33→			if !idxs.HasIndex(i) {
    34→				continue
    35→			}
    36→			// We won't check for file not found since the .Indices method should normally prevent that from happening.
    37→			sc, err := s.cfg.blobStorage.Get(b.Root(), i)
    38→			if err != nil {
    39→				s.writeErrorResponseToStream(responseCodeServerError, p2ptypes.ErrGeneric.Error(), stream)
    40→				return wQuota, errors.Wrapf(err, "could not retrieve sidecar: index %d, block root %#x", i, root)
    41→			}
    42→			SetStreamWriteDeadline(stream, defaultWriteDuration)
    43→			if chunkErr := WriteBlobSidecarChunk(stream, s.cfg.clock, s.cfg.p2p.Encoding(), sc); chunkErr != nil {
    44→				log.WithError(chunkErr).Debug("Could not send a chunked response")
    45→				s.writeErrorResponseToStream(responseCodeServerError, p2ptypes.ErrGeneric.Error(), stream)
    46→				tracing.AnnotateError(span, chunkErr)
    47→				return wQuota, chunkErr
    48→			}
    49→			s.rateLimiter.add(stream, 1)
    50→			wQuota -= 1
    51→			// Stop streaming results once the quota of writes for the request is consumed.
    52→			if wQuota == 0 {
    53→				return 0, nil
    54→			}
    55→		}
    56→	}
    57→	return wQuota, nil
    58→}
    59→
    60→// blobsSidecarsByRangeRPCHandler looks up the request blobs from the database from a given start slot index
    61→func (s *Service) blobSidecarsByRangeRPCHandler(ctx context.Context, msg interface{}, stream libp2pcore.Stream) error {
    62→	var err error
    63→	ctx, span := trace.StartSpan(ctx, "sync.BlobsSidecarsByRangeHandler")
    64→	defer span.End()
    65→	ctx, cancel := context.WithTimeout(ctx, respTimeout)
    66→	defer cancel()
    67→	SetRPCStreamDeadlines(stream)
    68→	log := log.WithField("handler", p2p.BlobSidecarsByRangeName[1:]) // slice the leading slash off the name var
    69→
    70→	r, ok := msg.(*pb.BlobSidecarsByRangeRequest)
    71→	if !ok {
    72→		return errors.New("message is not type *pb.BlobsSidecarsByRangeRequest")
    73→	}
    74→	if err := s.rateLimiter.validateRequest(stream, 1); err != nil {
    75→		return err
    76→	}
    77→
    78→	remotePeer := stream.Conn().RemotePeer()
    79→
    80→	rp, err := validateBlobsByRange(r, s.cfg.clock.CurrentSlot())
    81→	if err != nil {
    82→		s.writeErrorResponseToStream(responseCodeInvalidRequest, err.Error(), stream)
    83→		s.downscorePeer(remotePeer, "blobSidecarsByRangeRpcHandlerValidationError")
    84→		tracing.AnnotateError(span, err)
    85→		return err
    86→	}
    87→
    88→	// Ticker to stagger out large requests.
    89→	ticker := time.NewTicker(time.Second)
    90→	defer ticker.Stop()
    91→	batcher, err := newBlockRangeBatcher(rp, s.cfg.beaconDB, s.rateLimiter, s.cfg.chain.IsCanonical, ticker)
    92→	if err != nil {
    93→		log.WithError(err).Error("Cannot create new block range batcher")
    94→		s.writeErrorResponseToStream(responseCodeServerError, p2ptypes.ErrGeneric.Error(), stream)
    95→		tracing.AnnotateError(span, err)
    96→		return err
    97→	}
    98→
    99→	var batch blockBatch
   100→
   101→	wQuota := params.BeaconConfig().MaxRequestBlobSidecars
   102→	if slots.ToEpoch(s.cfg.clock.CurrentSlot()) >= params.BeaconConfig().ElectraForkEpoch {
   103→		wQuota = params.BeaconConfig().MaxRequestBlobSidecarsElectra
   104→	}
   105→	for batch, ok = batcher.next(ctx, stream); ok; batch, ok = batcher.next(ctx, stream) {
   106→		batchStart := time.Now()
   107→		wQuota, err = s.streamBlobBatch(ctx, batch, wQuota, stream)
   108→		rpcBlobsByRangeResponseLatency.Observe(float64(time.Since(batchStart).Milliseconds()))
   109→		if err != nil {
   110→			return err
   111→		}
   112→		// once we have written MAX_REQUEST_BLOB_SIDECARS, we're done serving the request
   113→		if wQuota == 0 {
   114→			break
   115→		}
   116→	}
   117→	if err := batch.error(); err != nil {
   118→		log.WithError(err).Debug("Error in BlobSidecarsByRange batch")
   119→
   120→		// If a rate limit is hit, it means an error response has already been sent and the stream has been closed.
   121→		if !errors.Is(err, p2ptypes.ErrRateLimited) {
   122→			s.writeErrorResponseToStream(responseCodeServerError, p2ptypes.ErrGeneric.Error(), stream)
   123→		}
   124→
   125→		tracing.AnnotateError(span, err)
   126→		return err
   127→	}
   128→
   129→	closeStream(stream, log)
   130→	return nil
   131→}
   132→
